const input=$input.first().json;const job=input.job??input;
const calendarId=job.target_id??job.payload?.calendarId??job.payload?.calendar_id;
if(job.kind!=='generate_rrss_plan'||!job.id||!job.client_id||!job.leaseToken||!calendarId)throw new Error('Contrato generate_rrss_plan v1 invalido: calendarId es obligatorio');
const payloadCalendar=job.payload?.calendarId??job.payload?.calendar_id;
if(String(calendarId)!==String(job.target_id)||(payloadCalendar&&String(payloadCalendar)!==String(calendarId)))throw new Error('calendarId debe coincidir con target_id');
return [{json:{job:{...job,target_id:calendarId,payload:{...job.payload,calendarId,calendar_id:calendarId}}}}];

// Shared by every client: values come only from the job payload (built by Infidash from editorial_config.rrss)
// and from editorial_config; there are no client-specific fallbacks.
const job=$('Validar trabajo').first().json.job;
const ctx=$('Cargar contexto Infidash').first().json;
const cfg=ctx.settings?.editorial_config??{};
const rrssCfg=cfg.rrss&&typeof cfg.rrss==='object'?cfg.rrss:{};
const requested=job.payload?.rrss&&typeof job.payload.rrss==='object'?job.payload.rrss:{};
const NETWORKS=['gmb','facebook','instagram'];
const text=(value)=>(value===undefined||value===null?'':String(value).trim());
const list=(value)=>Array.isArray(value)?value.map((item)=>text(item)).filter(Boolean):typeof value==='string'?value.split(',').map((item)=>item.trim()).filter(Boolean):[];
const positive=(value,max,fallback)=>{const number=Number(value);return Number.isInteger(number)&&number>0?Math.min(number,max):fallback;};
const topic=text(requested.topic)||text(rrssCfg.topic)||text(cfg.topic);
if(!topic)throw new Error('Falta el tema del plan de redes (editorial_config.rrss.topic o editorial_config.topic)');
const allowedNetworks=(value)=>[...new Set(list(value).map((network)=>network.toLowerCase()).filter((network)=>NETWORKS.includes(network)))];
const networks=[requested.networks,rrssCfg.networks].map(allowedNetworks).find((candidate)=>candidate.length)??[];
if(!networks.length)throw new Error('Faltan las redes sociales del plan de redes (editorial_config.rrss.networks)');
const keywordsList=[requested.keywords,rrssCfg.keywords].map(list).find((candidate)=>candidate.length)??[];
// Keywords fall back to the topic so the SerpAPI calls never send an empty q.
const keywords=keywordsList.length?keywordsList:[topic];
const postsPerWeek=positive(requested.postsPerWeek??rrssCfg.postsPerWeek,14,3);
const weeksHorizon=positive(requested.weeksHorizon??rrssCfg.weeksHorizon,12,4);
return [{json:{
  topic,
  brandName:text(cfg.brandName)||topic,
  country:text(rrssCfg.country)||text(cfg.country)||'ES',
  keywords:keywords.join(', '),
  keywords_list:keywords,
  networks,
  postsPerWeek,
  weeksHorizon,
  totalPosts:postsPerWeek*weeksHorizon,
  periodStart:job.payload?.periodStart??null,
}}];

const d = $input.item.json;
const rising = (d.related_queries?.rising || []).slice(0, 10);
