let text = $input.item.json.text || '{}';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { analysis_type: 'trends', resumen: 'Error al parsear salida del agente IA', error: e.message, raw: text };
}
if (!parsed.analysis_type) parsed.analysis_type = 'trends';
return [{ json: parsed }];

const tl = $input.item.json?.interest_over_time?.timeline_data || [];
const monthly = {};
tl.forEach(p => {
  const dt = new Date(p.timestamp * 1000);
  const k  = dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0');
  if (!monthly[k]) monthly[k] = [];
  monthly[k].push(parseInt(p.values?.[0]?.extracted_value || 0));
});
const avgs = Object.entries(monthly)
  .map(([m, v]) => ({ month: m, avg: Math.round(v.reduce((a, b) => a + b, 0) / v.length) }))
  .sort((a, b) => b.avg - a.avg);
return [{ json: {
  analysis_type:    'seasonal',
  monthly_interest: avgs,
  peak_month:       avgs[0]?.month || 'N/A',
  top_months:       avgs.slice(0, 4),
  seasonal_tip:     'Pico de interés detectado en ' + (avgs[0]?.month || 'N/A')
}}];

