let text = $input.item.json.text || '{}';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { analysis_type: 'seasonal', resumen: 'Error al parsear salida del agente IA', error: e.message, raw: text };
}
if (!parsed.analysis_type) parsed.analysis_type = 'seasonal';
return [{ json: parsed }];

const ctx=$('Cargar contexto Infidash').first().json;
const rrss=(ctx.rrssPlanItems??[]).filter((item)=>item&&item.title).map((item)=>({title:item.title,date:item.planned_at??null,status:item.status??null,format:item.format??null,networks:Array.isArray(item.networks)?item.networks:[]}));
const blog=(ctx.planItems??[]).filter((item)=>item&&item.title).slice(0,30).map((item)=>({title:item.title,date:item.planned_at??null,status:item.status??null}));
return [{json:{analysis_type:'existing_ideas',rrss_ideas:rrss,blog_articles:blog,used_titles:rrss.map((item)=>item.title),insights:rrss.length+' ideas de redes existentes; '+blog.length+' artículos del blog como inspiración.'}}];

const items = $input.all();
const find = (type) => items.find((item) => item.json.analysis_type === type)?.json || {};
const NA = '(sin datos)';
const list = (arr, mapper) => (!Array.isArray(arr) || arr.length === 0) ? '  ' + NA : arr.map((x) => '  - ' + (mapper ? mapper(x) : x)).join('\n');
// A stub (unavailable source) or a parse error never breaks the prompt.
const errBlock = (b) => b && b.unavailable
  ? '⚠️ Fuente no disponible (' + b.error + '). ' + (b.insights || NA)
  : b && b.error
  ? '⚠️ No se pudo parsear el análisis de este bloque (' + b.error + ').\nResumen crudo: ' + (b.insights || b.raw || NA)
  : null;

const trends = find('trends');
const trends_data = errBlock(trends) || [
  'Resumen: ' + (trends.resumen || NA),
  'Tendencias relevantes:',
  list(trends.tendencias_relevantes, (t) => t.query + ' (urgencia ' + t.urgencia + '): ' + t.motivo),
  'Ángulos para redes sociales:',
  list(trends.angulos_de_contenido)
].join('\n');

const seasonal = find('seasonal');
const seasonal_data = errBlock(seasonal) || [
  'Resumen: ' + (seasonal.resumen || NA),
  'Alerta estacional: ' + (seasonal.alerta_estacional || 'sin alertas próximas'),
  'Temas a anticipar:',
  list(seasonal.temas_a_anticipar),
  'Recomendación de timing: ' + (seasonal.recomendacion_timing || NA)
].join('\n');

const ideas = find('existing_ideas');
const existing_ideas_data = errBlock(ideas) || list(ideas.rrss_ideas, (x) => x.title + ' [' + (x.format || 'post') + ' · ' + ((x.networks || []).join(', ') || 'sin red') + ']');
const blog_articles_data = ideas.unavailable ? NA : list(ideas.blog_articles, (x) => x.title);

const cfg = $('⚙️ Configuración RRSS').first().json;
return [{ json: {
  trends_data,
  seasonal_data,
  existing_ideas_data,
  blog_articles_data,
  config: {
    topic:        cfg.topic,
    brandName:    cfg.brandName,
    country:      cfg.country,
    keywords:     cfg.keywords,
    networks:     (cfg.networks || []).join(', '),
    postsPerWeek: cfg.postsPerWeek,
    weeksHorizon: cfg.weeksHorizon,
    totalPosts:   cfg.totalPosts,
    periodStart:  cfg.periodStart
  }
}}];

