let text = $input.item.json.text || '{}';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
try {
  const plan = JSON.parse(text);
  return [{ json: { success: true, plan, raw: text } }];
} catch (e) {
  return [{ json: { success: false, error: e.message, raw: text } }];
}

const job=$('Validar trabajo').first().json.job;
const cfg=$('⚙️ Configuración RRSS').first().json;
const parsed=$('📝 Parsear Plan JSON').first().json;
if(!parsed.success||!Array.isArray(parsed.plan?.content_plan))throw new Error(parsed.error||'La IA no devolvio content_plan');
const calendarId=job.target_id;
if(!calendarId)throw new Error('calendarId es obligatorio');
const FORMATS=['post','reel','carousel','story'];
const allowed=Array.isArray(cfg.networks)?cfg.networks:[];
const dayOffset={lunes:0,martes:1,miercoles:2,'miércoles':2,jueves:3,viernes:4,sabado:5,'sábado':5,domingo:6};
const periodStart=job.payload?.periodStart??cfg.periodStart??null;
const base=periodStart?new Date(periodStart):null;
const words=(value)=>Array.isArray(value)?value:typeof value==='string'?value.split(','):[];
const out=[];
for(const week of parsed.plan.content_plan){
  for(const post of week?.posts??[]){
    if(!post?.title||!String(post.title).trim())throw new Error('Cada propuesta requiere title');
    if(post.calendarId&&String(post.calendarId)!==String(calendarId))throw new Error('La IA devolvió un calendarId distinto al reservado');
    let plannedAt=post.plannedAt??null;
    // Without a date from the AI, date the idea from periodStart: week N, weekday (Monday when unknown).
    if(!plannedAt&&base&&!Number.isNaN(base.getTime())){
      const date=new Date(base);
      date.setUTCDate(date.getUTCDate()+(Math.max(1,Number(week.week)||1)-1)*7+(dayOffset[String(post.day??'').trim().toLowerCase()]??0));
      plannedAt=date.toISOString();
    }
    if(!plannedAt||Number.isNaN(Date.parse(plannedAt)))throw new Error('plannedAt debe ser ISO-8601');
    const networks=[...new Set(words(post.networks).map((network)=>String(network).trim().toLowerCase()).filter((network)=>allowed.includes(network)))];
    const format=String(post.format??'').trim().toLowerCase();
    out.push({
      calendarId,
      title:String(post.title).trim(),
      theme:post.theme??week.theme??null,
      rationale:post.rationale??week.rationale??null,
      format:FORMATS.includes(format)?format:'post',
      networks:networks.length?networks:[...allowed],
      keywords:words(post.keywords).map((keyword)=>String(keyword).trim()).filter(Boolean),
      cta:post.cta??null,
      priority:post.priority??null,
      plannedAt:new Date(plannedAt).toISOString(),
      sourceKey:'rrss-plan:'+job.id+':'+out.length,
    });
  }
}
if(!out.length)throw new Error('El plan de redes no contiene propuestas');
return [{json:{schemaVersion:1,clientId:job.client_id,status:'succeeded',planItems:out,result:{count:out.length,summary:parsed.plan.summary??null,workflowVersion:1},leaseToken:job.leaseToken,jobId:job.id}}];
